a = {}

def winOrLose(x, y):
	if (x > y):
		return winOrLose(y, x)
	if (a[x] == y):
		return False
	return True

def compute():
	a[0] = 0
	d = 1
	for i in range(1000007):
		if(i in a):
			continue
		else:
			a[i] = i + d
			a[i + d] = i
			d += 1
compute()
